import MockDate from 'mockdate';

import * as db from '#server/db';
import { loadMappings } from '#server/db/mappings';
import { loadRules } from '#server/transactions/transaction-rules';

import { findSchedules } from './find-schedules';

beforeEach(async () => {
  await global.emptyDatabase()();
  await loadMappings();
  await loadRules();
  // A Wednesday, so a pattern built from today's weekday can't
  // accidentally match the Monday transactions below.
  MockDate.set(new Date(2024, 10, 6));
});

afterEach(() => {
  MockDate.reset();
});

async function insertPayments(accountId: string, dates: string[]) {
  await db.insertAccount({ id: accountId, name: accountId });
  const payee = await db.insertPayee({ name: 'Payee ' + accountId });
  for (const date of dates) {
    await db.insertTransaction({
      account: accountId,
      payee,
      date,
      amount: -5000,
    });
  }
}

describe('findSchedules', () => {
  test('finds a schedule on the 1st and 3rd Monday of the month', async () => {
    await insertPayments('acct1', [
      '2024-07-01',
      '2024-07-15',
      '2024-08-05',
      '2024-08-19',
      '2024-09-02',
      '2024-09-16',
      '2024-10-07',
      '2024-10-21',
    ]);

    const [schedule] = await findSchedules();

    expect(schedule.date).toMatchObject({
      frequency: 'monthly',
      patterns: [
        { type: 'MO', value: 1 },
        { type: 'MO', value: 3 },
      ],
    });
  });

  test('finds a schedule on the 2nd and 4th Monday of the month', async () => {
    await insertPayments('acct1', [
      '2024-07-08',
      '2024-07-22',
      '2024-08-12',
      '2024-08-26',
      '2024-09-09',
      '2024-09-23',
      '2024-10-14',
      '2024-10-28',
    ]);

    const [schedule] = await findSchedules();

    expect(schedule.date).toMatchObject({
      frequency: 'monthly',
      patterns: [
        { type: 'MO', value: 2 },
        { type: 'MO', value: 4 },
      ],
    });
  });
});

