    subtransactions: [
      { amount: -5000, category: ids.groceries },
      { amount: -3000, payee: ids.tpSavings },
    ],
  });
  await verify('S7', { allowSplitErrors: [s1.id] });

  step('S8 split in an off-budget account and a child transfer to on-budget');
  await add(A, ids.brokerage, [
    {
      date: '2026-10-17', amount: -20000, payee: ids.shop,
      subtransactions: [
        { amount: -15000, payee: ids.tpChecking, category: ids.office },
        { amount: -5000 },
      ],
    },
  ]);
  await verify('S8', { allowSplitErrors: [s1.id] });

  // ---- Merges ----
  step('M1 merge manual entry with its imported duplicate');
  await add(A, ids.checking, [{ date: '2026-10-20', amount: -2500, payee: ids.shop, category: ids.groceries }]);
  await A.run(`await api.importTransactions(args.acct, [{ date: '2026-10-21', amount: -2500, payee_name: 'SUPERMARKET 123', imported_id: 'bank-1' }], { defaultCleared: true });`, { acct: ids.checking });
  // reconcile may already have matched it; find all rows of that amount
  let m1 = await A.run(`return await db.all("SELECT * FROM v_transactions_internal WHERE acct = ? AND amount = -2500 AND tombstone = 0", [args.acct]);`, { acct: ids.checking });
  if (m1.length === 2) await A.run(`return await api.mergeTransactions(args.ids);`, { ids: m1.map(t => t.id) });
  await verify('M1');

  step('M2 merge a manual transfer with a plain imported row');
  await add(A, ids.checking, [{ date: '2026-10-22', amount: -3300, payee: ids.tpSavings }]);
  await add(A, ids.checking, [{ date: '2026-10-22', amount: -3300, imported_id: 'bank-2', imported_payee: 'TRANSFER TO SAVINGS', notes: 'bank text' }]);
  const m2 = await A.run(`return await db.all("SELECT * FROM v_transactions_internal WHERE acct = ? AND amount = -3300 AND tombstone = 0", [args.acct]);`, { acct: ids.checking });
  await A.run(`return await api.mergeTransactions(args.ids);`, { ids: m2.map(t => t.id) });
  await verify('M2', { allowSplitErrors: [s1.id] });

  step('M3 merge two transfers to the same account');
  await add(A, ids.checking, [{ date: '2026-10-23', amount: -4400, payee: ids.tpSavings }]);
  await add(A, ids.checking, [{ date: '2026-10-24', amount: -4400, payee: ids.tpSavings }]);
  const m3 = await A.run(`return await db.all("SELECT * FROM v_transactions_internal WHERE acct = ? AND amount = -4400 AND tombstone = 0", [args.acct]);`, { acct: ids.checking });
  await A.run(`return await api.mergeTransactions(args.ids);`, { ids: m3.map(t => t.id) });
  await verify('M3', { allowSplitErrors: [s1.id] });

  step('M4 merge a split with a plain duplicate (on laptop B)');
  await add(B, ids.checking, [
    { date: '2026-10-25', amount: -5500, payee: ids.shop, subtransactions: [{ amount: -5000, category: ids.groceries }, { amount: -500, category: ids.office }] },
