// Drives two laptops (separate processes, separate data dirs) against one
// sync server, through real transfer / split / merge / delete flows, and
// checks bookkeeping invariants plus A == B after every sync.
const { fork } = require('child_process');
const path = require('path');
const fs = require('fs');

const ROOT = path.join(__dirname, 'run-' + Date.now());
const failures = [];
let stepName = '';

function startLaptop(name) {
  const child = fork(path.join(__dirname, 'laptop.cjs'), [
    name,
    path.join(ROOT, name),
  ]);
  let seq = 0;
  const pending = new Map();
  const ready = new Promise(resolve => {
    child.on('message', msg => {
      if (msg.ready) return resolve();
      const p = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) p.reject(new Error(`[${name}] ${msg.error}`));
      else p.resolve(msg.result);
    });
  });
  return {
    name,
    child,
    ready,
    run(code, args) {
      const id = ++seq;
      return new Promise((resolve, reject) => {
        pending.set(id, { resolve, reject });
        child.send({ id, code, args });
      });
    },
  };
}

const A = startLaptop('A');
const B = startLaptop('B');

// ---------- snapshot + invariants ----------

const SNAPSHOT = `
  const months = args.months;
  const tx = await db.all('SELECT * FROM v_transactions_internal ORDER BY id');
  const accounts = await db.all('SELECT id, name, offbudget, closed, tombstone FROM accounts ORDER BY id');
  const payees = await db.all('SELECT id, name, transfer_acct, tombstone FROM payees ORDER BY id');
  const budgets = await db.all('SELECT id, month, category, amount FROM zero_budgets ORDER BY id');
  const balances = {};
  for (const a of accounts.filter(a => !a.tombstone)) {
    balances[a.id] = await api.getAccountBalance(a.id);
  }
  const sheet = {};
  for (const m of months) {
    const bm = await api.getBudgetMonth(m);
    sheet[m] = {
      toBudget: bm.toBudget,
      cats: Object.fromEntries(
        bm.categoryGroups.flatMap(g => g.categories).map(c => [c.id, { budgeted: c.budgeted, spent: c.spent, balance: c.balance }]),
      ),
    };
  }
  return { tx, accounts, payees, budgets, balances, sheet };
`;

function fail(msg) {
  failures.push(`[${stepName}] ${msg}`);
  console.log(`   ✗ ${msg}`);
}

function checkInvariants(label, s, { allowSplitErrors = [] } = {}) {
  const byId = new Map(s.tx.map(t => [t.id, t]));
  const payeeById = new Map(s.payees.map(p => [p.id, p]));
  const acctById = new Map(s.accounts.map(a => [a.id, a]));
  const isAlive = t =>
    t &&
    !t.tombstone &&
    (!t.is_child || (byId.get(t.parent_id) && !byId.get(t.parent_id).tombstone));
  const alive = s.tx.filter(isAlive);
  const before = failures.length;

  for (const t of alive) {
    const payee = payeeById.get(t.payee);
    const transferAcct = payee && !payee.tombstone ? payee.transfer_acct : null;

    if (t.transfer_id) {
      const o = byId.get(t.transfer_id);
      if (!isAlive(o)) {
        fail(`${label}: ${t.id} points at missing/deleted transfer ${t.transfer_id}`);
        continue;
      }
      if (o.transfer_id !== t.id) fail(`${label}: ${t.id} -> ${o.id} but ${o.id} -> ${o.transfer_id}`);
      if (o.amount !== -t.amount) fail(`${label}: transfer amounts ${t.id}=${t.amount} vs ${o.id}=${o.amount}`);
      if (o.date !== t.date) fail(`${label}: transfer dates ${t.id}=${t.date} vs ${o.id}=${o.date}`);
      if (transferAcct !== o.account) fail(`${label}: ${t.id} payee points at ${transferAcct} but counterpart lives in ${o.account}`);
      const a1 = acctById.get(t.account), a2 = acctById.get(o.account);
      if (a1 && a2 && a1.offbudget === a2.offbudget && t.category) {
        fail(`${label}: same-budget-type transfer ${t.id} still has category ${t.category}`);
      }
    } else if (transferAcct && !t.is_parent) {
      fail(`${label}: ${t.id} has transfer payee (${transferAcct}) but no counterpart`);
    }

    if (t.is_parent) {
      const kids = alive.filter(c => c.parent_id === t.id);
      const sum = kids.reduce((a, c) => a + c.amount, 0);
      if (kids.length === 0) fail(`${label}: parent ${t.id} has no children`);
      if (sum !== t.amount && !allowSplitErrors.includes(t.id)) fail(`${label}: split ${t.id} amount ${t.amount} != children ${sum}`);
      for (const c of kids) {
        if (c.account !== t.account) fail(`${label}: child ${c.id} account differs from parent`);
        if (c.date !== t.date) fail(`${label}: child ${c.id} date ${c.date} differs from parent ${t.date}`);
      }
      if (t.category) fail(`${label}: parent ${t.id} has a category`);
    }
  }

  // Orphans: alive child rows whose parent is gone, that still carry a live transfer
  for (const t of s.tx.filter(t => !t.tombstone && t.is_child && !isAlive(t))) {
    const o = t.transfer_id && byId.get(t.transfer_id);
    if (o && isAlive(o)) fail(`${label}: deleted split left counterpart ${o.id} alive in ${o.account}`);
  }

  // Balances = sum of alive non-parent rows
  for (const [acct, bal] of Object.entries(s.balances)) {
    const sum = alive.filter(t => t.account === acct && !t.is_parent).reduce((a, t) => a + t.amount, 0);
    if (sum !== bal) fail(`${label}: balance of ${acctById.get(acct).name} = ${bal}, rows sum to ${sum}`);
  }

  // Budget "spent" = sum of alive non-parent rows in on-budget accounts
  for (const [month, data] of Object.entries(s.sheet)) {
    const mm = Number(month.replace('-', ''));
    for (const [cat, v] of Object.entries(data.cats)) {
      const sum = alive
        .filter(t => !t.is_parent && t.category === cat && Math.floor(t.date / 100) === mm && acctById.get(t.account)?.offbudget === 0)
        .reduce((a, t) => a + t.amount, 0);
      if (sum !== v.spent) fail(`${label}: ${month} category ${cat} spent ${v.spent}, rows sum to ${sum}`);
    }
  }
  if (failures.length === before) console.log(`   ✓ ${label}: invariants hold (${alive.length} live rows)`);
}

function stable(s) {
  // Strip local-only noise; everything else must match between laptops
  return JSON.stringify(s);
}

function diffSnapshots(a, b) {
  const out = [];
  const ta = new Map(a.tx.map(t => [t.id, t]));
  const tb = new Map(b.tx.map(t => [t.id, t]));
  for (const id of new Set([...ta.keys(), ...tb.keys()])) {
    const x = ta.get(id), y = tb.get(id);
    if (JSON.stringify(x) !== JSON.stringify(y)) {
      if (!x || !y) out.push(`tx ${id} only on ${x ? 'A' : 'B'}`);
      else for (const k of Object.keys(x)) if (JSON.stringify(x[k]) !== JSON.stringify(y[k])) out.push(`tx ${id}.${k}: A=${JSON.stringify(x[k])} B=${JSON.stringify(y[k])}`);
    }
  }
  for (const k of ['accounts', 'payees', 'budgets', 'balances', 'sheet']) {
    if (JSON.stringify(a[k]) !== JSON.stringify(b[k])) out.push(`${k} differ: A=${JSON.stringify(a[k]).slice(0, 400)} B=${JSON.stringify(b[k]).slice(0, 400)}`);
  }
  return out;
}

const MONTHS = ['2026-09', '2026-10', '2026-11'];
async function snap(l) {
  return l.run(SNAPSHOT, { months: MONTHS });
}

async function syncBoth() {
  // A pushes, B pulls+pushes, A pulls
  await A.run('await api.sync();');
  await B.run('await api.sync();');
  await A.run('await api.sync();');
}

async function verify(label, opts) {
  await syncBoth();
  const [sa, sb] = await Promise.all([snap(A), snap(B)]);
  checkInvariants(label + ' (A)', sa, opts);
  const d = diffSnapshots(sa, sb);
  if (d.length) for (const line of d.slice(0, 15)) fail(`${label}: A/B diverged: ${line}`);
  else console.log(`   ✓ ${label}: laptops identical`);
  return sa;
}

function step(name) {
  stepName = name;
  console.log(`\n== ${name}`);
}

// ---------- scenarios ----------

async function main() {
  await Promise.all([A.ready, B.ready]);

  step('Setup on laptop A, download on laptop B');
  const ids = await A.run(`
    await send('create-budget', { budgetName: 'Household and Business' });
    const checking = await api.createAccount({ name: 'Checking', offbudget: false }, 500000);
    const savings = await api.createAccount({ name: 'Savings', offbudget: false }, 0);
    const business = await api.createAccount({ name: 'Business', offbudget: false }, 0);
    const brokerage = await api.createAccount({ name: 'Brokerage', offbudget: true }, 0);
    const group = await api.createCategoryGroup({ name: 'Test' });
    const groceries = await api.createCategory({ name: 'Groceries', group_id: group });
    const rent = await api.createCategory({ name: 'Rent', group_id: group });
    const office = await api.createCategory({ name: 'Office', group_id: group });
    const payees = await api.getPayees();
    const tp = id => payees.find(p => p.transfer_acct === id).id;
    const shop = await api.createPayee({ name: 'Supermarket' });
    const landlord = await api.createPayee({ name: 'Landlord' });
    await api.sync();
    const budgets = await api.getBudgets();
    const prefs = await send('load-prefs');
    return { checking, savings, business, brokerage, groceries, rent, office, shop, landlord,
      tpChecking: tp(checking), tpSavings: tp(savings), tpBusiness: tp(business), tpBrokerage: tp(brokerage),
      groupId: prefs.groupId };
  `);
  await B.run(`await api.downloadBudget(args.groupId);`, { groupId: ids.groupId });
  await verify('initial download');

  const add = (laptop, acct, txs) =>
    laptop.run(
      `await api.addTransactions(args.acct, args.txs, { runTransfers: true, learnCategories: false });
       const rows = await db.all("SELECT id FROM v_transactions_internal WHERE acct = ? AND tombstone = 0 AND isChild = 0 ORDER BY sort_order DESC", [args.acct]);
       return rows.map(r => r.id);`,
      { acct, txs },
    );
  const findTx = (laptop, where, params = []) =>
    laptop.run(`return await db.first('SELECT * FROM v_transactions_internal WHERE ' + args.where, args.params);`, { where, params });
  const update = (laptop, id, fields) => laptop.run(`return await api.updateTransaction(args.id, args.fields);`, { id, fields });
  const del = (laptop, id) => laptop.run(`return await api.deleteTransaction(args.id);`, { id });

  // ---- Transfers ----
  step('T1 add transfer Checking -> Savings');
  await add(A, ids.checking, [{ date: '2026-10-05', amount: -50000, payee: ids.tpSavings, notes: 'move' }]);
  let t1 = await findTx(A, "acct = ? AND amount = -50000 AND tombstone = 0", [ids.checking]);
  await verify('T1');

  step('T2 edit transfer amount from the Checking side');
  await update(A, t1.id, { amount: -60000 });
  await verify('T2');

  step('T3 edit transfer date and notes');
  await update(A, t1.id, { date: '2026-10-07', notes: 'moved later' });
  await verify('T3');

  step('T4 edit amount from the Savings side (laptop B)');
  t1 = await findTx(B, 'id = ?', [t1.id]);
  await update(B, t1.transfer_id, { amount: 70000 });
  await verify('T4');

  step('T5 retarget transfer to Business');
  await update(A, t1.id, { payee: ids.tpBusiness });
  await verify('T5');

  step('T6 retarget to off-budget Brokerage with a category');
  await update(A, t1.id, { payee: ids.tpBrokerage, category: ids.office });
  const t6 = await findTx(A, 'id = ?', [t1.id]);
  if (t6.category !== ids.office) fail(`on->off budget transfer lost its category (got ${t6.category})`);
  await verify('T6');

  step('T7 turn transfer into a normal payment');
  await update(A, t1.id, { payee: ids.landlord, category: ids.rent });
  await verify('T7');

  step('T8 make it a transfer again, then delete it from the counterpart side');
  await update(A, t1.id, { payee: ids.tpSavings });
  await syncBoth();
  t1 = await findTx(B, 'id = ?', [t1.id]);
  await del(B, t1.transfer_id);
  const t8 = await findTx(A, 'id = ?', [t1.id]);
  await verify('T8');

  step('T9 move a transfer to a different account');
  await add(A, ids.checking, [{ date: '2026-10-10', amount: -1234, payee: ids.tpSavings }]);
  let t9 = await findTx(A, "acct = ? AND amount = -1234 AND tombstone = 0", [ids.checking]);
  await update(A, t9.id, { account: ids.business });
  await verify('T9');

