async function latestAmountTimestamp(id: string): Promise<string> {
  const row = await db.first<{ timestamp: string | null }>(
    `SELECT MAX(timestamp) AS timestamp FROM messages_crdt
      WHERE dataset = 'transactions' AND row = ? AND column = 'amount'`,
    [id],
  );
  return row?.timestamp ?? '';
}

/**
 * Bring the two sides of a transfer back in line when they no longer
 * mirror each other's amount.
 *
 * Each edit updates both sides, but sync resolves every field on its own.
 * When two devices change the two sides of the same transfer at the same
 * time, each side can end up keeping a different device's amount. The side
 * whose amount was written last wins. Every device eventually holds the same
 * sync history, so they all pick the same winner and converge.
 */
export async function repairTransferAmounts(): Promise<string[]> {
  const mismatched = await db.all<{
    id: string;
    amount: number;
    other_id: string;
    other_amount: number;
  }>(
    `SELECT t1.id, t1.amount, t2.id AS other_id, t2.amount AS other_amount
       FROM v_transactions_internal_alive t1
       JOIN v_transactions_internal_alive t2
         ON t2.id = t1.transfer_id AND t2.transfer_id = t1.id
      WHERE t1.amount != -t2.amount AND t1.id < t2.id`,
  );

  const repaired: string[] = [];
  for (const pair of mismatched) {
    const [ts, otherTs] = await Promise.all([
      latestAmountTimestamp(pair.id),
      latestAmountTimestamp(pair.other_id),
    ]);
    // Ties (no history, e.g. after a sync reset) fall to the lower id,
    // which every device agrees on.
    const keepFirst = ts >= otherTs;
    const target = keepFirst ? pair.other_id : pair.id;
    const amount = keepFirst ? -pair.amount : -pair.other_amount;
    await db.updateTransaction({ id: target, amount });
    repaired.push(target);
  }
  return repaired;
}

