test('bank sync updating dates keeps a matched split line with its split', async () => {
  const { id } = await prepareDatabase();

  await db.insertTransaction({
    id: 'split-parent',
    account: id,
    amount: -1000,
    date: '2024-03-31',
    is_parent: true,
  });
  await db.insertTransaction({
    id: 'split-child-1',
    account: id,
    amount: -299,
    date: '2024-03-31',
    is_child: true,
    parent_id: 'split-parent',
  });
  await db.insertTransaction({
    id: 'split-child-2',
    account: id,
    amount: -701,
    date: '2024-03-31',
    is_child: true,
    parent_id: 'split-parent',
  });

  // The bank reports the matched line two days later, in the next month
  await reconcileTransactions(
    id,
    [
      {
        transactionId: 'child-provider-id',
        transactionAmount: { amount: '-2.99' },
        date: '2024-04-02',
        payeeName: 'Child merchant',
        booked: true,
      },
    ],
    { isBankSyncAccount: true, strictIdChecking: false, updateDates: true },
  );

  const transactions = await getAllTransactions();
  const dates = Object.fromEntries(
    transactions
      .filter(transaction => transaction.id.startsWith('split-'))
      .map(transaction => [transaction.id, transaction.date]),
  );
  // The line stays in March with the rest of its split
  expect(dates).toEqual({
    'split-parent': 20240331,
    'split-child-1': 20240331,
    'split-child-2': 20240331,
  });
});

