cat > bankproxy.cjs <<'EOF'
// Fake bank in front of the real sync server: /simplefin/* returns a feed
// set via POST /__feed; everything else is forwarded to the sync server.
const http = require('http');
let feed = {}; // accountId -> { transactions, startingBalance }
const server = http.createServer((req, res) => {
  const chunks = [];
  req.on('data', c => chunks.push(c));
  req.on('end', () => {
    const body = Buffer.concat(chunks);
    if (req.url === '/__feed') {
      feed = JSON.parse(body.toString());
      res.end('ok');
      return;
    }
    if (req.url.startsWith('/simplefin/transactions')) {
      const { accountId } = JSON.parse(body.toString());
      const make = id => {
        const f = feed[id] || { transactions: [], startingBalance: 0 };
        return { transactions: { all: f.transactions, booked: f.transactions, pending: [] }, balances: [], startingBalance: f.startingBalance };
      };
      const data = Array.isArray(accountId)
        ? Object.fromEntries(accountId.map(id => [id, make(id)]).concat([['errors', {}]]))
        : make(accountId);
      res.setHeader('Content-Type', 'application/json');
      res.end(JSON.stringify({ status: 'ok', data }));
      return;
    }
    const fwd = http.request({ host: '127.0.0.1', port: 5077, path: req.url, method: req.method, headers: req.headers }, r => {
      res.writeHead(r.statusCode, r.headers);
      r.pipe(res);
    });
    fwd.on('error', e => { res.statusCode = 502; res.end(String(e)); });
    fwd.end(body);
  });
});
server.listen(5078, '127.0.0.1', () => console.log('proxy on 5078'));
EOF
echo ok

