// Both laptops pull the same bank account (real bank-sync code path via a
// fake SimpleFIN feed) and import the same files, before syncing with each
// other. Then they sync and we look for duplicates.
const { fork } = require('child_process');
const http = require('http');
const path = require('path');

const ROOT = path.join(__dirname, 'dupes-' + Date.now());
const problems = [];

function startLaptop(name) {
  const child = fork(path.join(__dirname, 'laptop.cjs'), [name, path.join(ROOT, name)], {
    env: { ...process.env, SERVER_URL: 'http://127.0.0.1:5078' },
  });
  let seq = 0;
  const pending = new Map();
  const ready = new Promise(resolve => {
    child.on('message', msg => {
      if (msg.ready) return resolve();
      const p = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) p.reject(new Error(`[${name}] ${msg.error}`));
      else p.resolve(msg.result);
    });
  });
  return {
    name, child, ready,
    run(code, args) {
      const id = ++seq;
      return new Promise((resolve, reject) => {
        pending.set(id, { resolve, reject });
        child.send({ id, code, args });
      });
    },
  };
}

function setFeed(feed) {
  return new Promise((resolve, reject) => {
    const req = http.request({ host: '127.0.0.1', port: 5078, path: '/__feed', method: 'POST' }, res => { res.resume(); res.on('end', resolve); });
    req.on('error', reject);
    req.end(JSON.stringify(feed));
  });
}

const A = startLaptop('A');
const B = startLaptop('B');

async function syncBoth() {
  await A.run('await api.sync();');
  await B.run('await api.sync();');
  await A.run('await api.sync();');
  await B.run('await api.sync();');
}

const REPORT = `
  const rows = await db.all("SELECT t.id, t.account, t.amount, t.date, t.imported_id, t.starting_balance_flag, t.category, t.payee, t.notes, t.is_parent, t.is_child, t.parent_id, t.transfer_id FROM v_transactions_internal_alive t WHERE t.account = ? ORDER BY t.date, t.amount, t.id", [args.acct]);
  const payees = await db.all("SELECT id, name FROM payees WHERE tombstone = 0 AND transfer_acct IS NULL ORDER BY name");
  const balance = await api.getAccountBalance(args.acct);
  return { rows, payees, balance };
`;

function describe(label, report, expected) {
  const top = report.rows.filter(r => !r.is_child);
  const byImported = {};
  for (const r of top) if (r.imported_id) (byImported[r.imported_id] ||= []).push(r);
  const dupIds = Object.entries(byImported).filter(([, v]) => v.length > 1);
  const starting = top.filter(r => r.starting_balance_flag);
  const payeeNames = report.payees.map(p => p.name);
  const dupPayees = payeeNames.filter((n, i) => payeeNames.indexOf(n) !== i);
  console.log(`   ${label}: ${top.length} transactions (expected ${expected.count}), ${starting.length} opening balance row(s), balance ${report.balance} (expected ${expected.balance})`);
  if (dupIds.length) console.log(`     duplicated bank ids: ${dupIds.map(([k, v]) => `${k}×${v.length}`).join(', ')}`);
  if (dupPayees.length) console.log(`     duplicated payees: ${[...new Set(dupPayees)].join(', ')}`);
  if (top.length !== expected.count) problems.push(`${label}: ${top.length} transactions, expected ${expected.count}`);
  if (report.balance !== expected.balance) problems.push(`${label}: balance ${report.balance}, expected ${expected.balance}`);
  if (dupPayees.length) problems.push(`${label}: duplicated payees ${[...new Set(dupPayees)].join(', ')}`);
  if (starting.length > 1) problems.push(`${label}: ${starting.length} opening balances`);
}

const tx = (id, date, amount, payeeName) => ({
  transactionId: id, date, payeeName, booked: true,
  transactionAmount: { amount: (amount / 100).toFixed(2), currency: 'GBP' },
});

async function main() {
  await Promise.all([A.ready, B.ready]);

  console.log('== Setup');
  const ids = await A.run(`
    await send('create-budget', { budgetName: 'Dupes' });
    const checking = await api.createAccount({ name: 'Joint current', offbudget: false });
    const card = await api.createAccount({ name: 'Business card', offbudget: false });
    const csvAcct = await api.createAccount({ name: 'Savings (CSV)', offbudget: false });
    await db.insert('banks', { id: 'bank-1', bank_id: 'sf-bank', name: 'Bank' });
    await db.update('accounts', { id: checking, bank: 'bank-1', account_id: 'sf-joint', account_sync_source: 'simpleFin' });
    const group = await api.createCategoryGroup({ name: 'Spend' });
    const groceries = await api.createCategory({ name: 'Groceries', group_id: group });
    const office = await api.createCategory({ name: 'Office', group_id: group });
    // A rule both laptops will run while importing
    await api.createRule({ stage: null, conditionsOp: 'and',
      conditions: [{ op: 'contains', field: 'imported_payee', value: 'tesco' }],
      actions: [{ op: 'set', field: 'category', value: groceries }] });
    await api.sync();
    const prefs = await send('load-prefs');
    return { checking, card, csvAcct, groceries, office, groupId: prefs.groupId };
  `);
  await B.run('await api.downloadBudget(args.groupId);', { groupId: ids.groupId });

  // ---------- Bank sync ----------
  const day1 = [
    tx('b-1', '2026-11-02', -1250, 'TESCO STORES'),
    tx('b-2', '2026-11-03', -4599, 'AMAZON MKTPLACE'),
    tx('b-3', '2026-11-05', 250000, 'ACME LTD SALARY'),
    tx('b-4', '2026-11-06', -80000, 'RENT LANDLORD'),
    tx('b-5', '2026-11-07', -320, 'COSTA COFFEE'),
  ];
  // Current balance 1,000.00; the opening balance is derived from it
  await setFeed({ 'sf-joint': { transactions: [...day1].reverse(), startingBalance: 100000 } });

  console.log('\n== I1 both laptops bank-sync a new account before syncing with each other');
  const [ra, rb] = await Promise.all([
    A.run(`return await send('accounts-bank-sync', { ids: [args.acct] });`, { acct: ids.checking }),
    B.run(`return await send('accounts-bank-sync', { ids: [args.acct] });`, { acct: ids.checking }),
  ]);
  if (ra.errors?.length || rb.errors?.length) console.log('   bank sync errors', JSON.stringify(ra.errors), JSON.stringify(rb.errors));
  await syncBoth();
  describe('I1 laptop A', await A.run(REPORT, { acct: ids.checking }), { count: 6, balance: 100000 });
  describe('I1 laptop B', await B.run(REPORT, { acct: ids.checking }), { count: 6, balance: 100000 });

  console.log('\n== I2 next day: both laptops bank-sync again before syncing with each other');
  const day2 = [...day1, tx('b-6', '2026-11-09', -2200, 'TESCO EXPRESS'), tx('b-7', '2026-11-10', -1500, 'TRAINLINE')];
  await setFeed({ 'sf-joint': { transactions: [...day2].reverse(), startingBalance: 96300 } });
  await Promise.all([
    A.run(`return await send('accounts-bank-sync', { ids: [args.acct] });`, { acct: ids.checking }),
    B.run(`return await send('accounts-bank-sync', { ids: [args.acct] });`, { acct: ids.checking }),
  ]);
  await syncBoth();
