import { v4 as uuidv4, v5 as uuidv5 } from 'uuid';

import * as db from '#server/db';

// Namespace for ids derived from what a row represents (see `stableId`)
const NAMESPACE = 'b1f3c7d2-5e8a-4c6b-9f0d-2a7e4b8c1d35';

/**
 * An id derived from what a row represents rather than a random one.
 *
 * When two devices import the same bank account or file before syncing with
 * each other, random ids turn every transaction (and its payee, opening
 * balance, split lines and transfer) into two rows once they sync. With the
 * same id on both devices they are the same row, and sync merges the two
 * writes field by field like any other edit.
 */
export function stableId(...parts: Array<string | number | null | undefined>) {
  return uuidv5(JSON.stringify(parts.map(part => part ?? null)), NAMESPACE);
}

/**
 * `stableId`, unless a row with that id already exists in `table` (for
 * example one that was deleted or merged away): then a random id, so an old
 * row is never brought back or written over.
 */
export async function unusedStableId(
  table: 'transactions' | 'payees',
  ...parts: Array<string | number | null | undefined>
): Promise<string> {
  const id = stableId(...parts);
  const existing = await db.first<{ id: string }>(
    `SELECT id FROM ${table} WHERE id = ?`,
    [id],
  );
  return existing ? uuidv4() : id;
}

type ImportedTransaction = {
  imported_id?: string | null;
  date?: string | null;
  amount?: number | null;
  imported_payee?: string | null;
  notes?: string | null;
};

/**
 * Ids for transactions about to be created from imported data (bank sync or
 * a file), in import order.
 *
 * A bank id identifies the transaction on its own. Without one (CSV, QIF)
 * the date, amount, bank payee and notes do, counting repeats within the
 * import so that two identical transactions on the same day stay two.
 */
export async function importedTransactionIds(
  accountId: string,
  transactions: ImportedTransaction[],
): Promise<string[]> {
  const seen = new Map<string, number>();
  const ids: string[] = [];
  for (const trans of transactions) {
    if (trans.imported_id) {
      ids.push(
        await unusedStableId(
          'transactions',
          'imported',
          accountId,
          trans.imported_id,
        ),
      );
      continue;
    }
    const content = JSON.stringify([
      trans.date,
      trans.amount,
      trans.imported_payee,
      trans.notes,
    ]);
    const occurrence = seen.get(content) ?? 0;
    seen.set(content, occurrence + 1);
    ids.push(
      await unusedStableId(
        'transactions',
        'imported-content',
        accountId,
        content,
        occurrence,
      ),
    );
  }
  return ids;
}

import * as db from '#server/db';
import { whereIn } from '#server/db/util';
import { fromDateRepr } from '#server/models';

/**
 * Put every line of a split back on its parent's date and account.
 *
 * A split is one transaction, so its lines must always share the parent's
 * date and account; otherwise a line can be counted in a different month
 * or account than the rest of the split. Anything that moves only the
 * parent or only a line (a rule setting the date, bank sync updating dates,
 * a merge, an edit on another device) is corrected here, and the parent
 * always wins.
 *
 * Pass the parent ids to check, or nothing to check every split. Returns the
 * ids of the lines that were moved.
 */
export async function alignSplitLines(parentIds?: string[]): Promise<string[]> {
  if (parentIds && parentIds.length === 0) {
    return [];
  }

  const rows = await db.all<{ id: string; date: number; account: string }>(
    `SELECT c.id, p.date, p.account
       FROM v_transactions_internal_alive c
       JOIN v_transactions_internal_alive p ON p.id = c.parent_id
      WHERE c.is_child = 1 AND p.is_parent = 1
        AND (c.date != p.date OR c.account != p.account)
        ${parentIds ? 'AND ' + whereIn(parentIds, 'p.id') : ''}`,
  );

  for (const row of rows) {
    await db.updateTransaction({
      id: row.id,
      date: fromDateRepr(row.date),
      account: row.account,
    });
  }

  return rows.map(row => row.id);
}

/**
 * The parents of the splits that the given transactions belong to (a
 * parent maps to itself, a line to its parent).
 */
export async function getSplitParentIds(ids: string[]): Promise<string[]> {
  if (ids.length === 0) {
    return [];
  }
  const rows = await db.all<{ parent: string }>(
    `SELECT DISTINCT CASE WHEN is_child = 1 THEN parent_id ELSE id END AS parent
       FROM v_transactions_internal
      WHERE (is_parent = 1 OR is_child = 1) AND ${whereIn(ids, 'id')}`,
  );
  return rows.map(row => row.parent).filter(Boolean);
}

import { beforeEach, describe, expect, it } from 'vitest';

import * as db from '#server/db';

import { mergeTransactions } from './merge';
import { alignSplitLines } from './split-lines';

import { batchUpdateTransactions } from './index';

beforeEach(global.emptyDatabase());

async function setup() {
  await db.insertAccount({ id: 'one', name: 'one' });
  await db.insertAccount({ id: 'two', name: 'two' });
  await db.insertPayee({ id: 'transfer-one', name: '', transfer_acct: 'one' });
  await db.insertPayee({ id: 'transfer-two', name: '', transfer_acct: 'two' });
  await db.insertAccount({ id: 'three', name: 'three' });
  await db.insertPayee({
    id: 'transfer-three',
    name: '',
    transfer_acct: 'three',
  });

  await batchUpdateTransactions({
    added: [
      {
        id: 'parent',
        account: 'one',
        amount: -100,
        date: '2024-01-31',
        is_parent: true,
      },
      {
        id: 'line1',
        account: 'one',
        amount: -60,
        date: '2024-01-31',
        is_child: true,
        parent_id: 'parent',
      },
      {
        id: 'line2',
        account: 'one',
        amount: -40,
        date: '2024-01-31',
        is_child: true,
        parent_id: 'parent',
        payee: 'transfer-three',
      },
    ],
  });
}

function getLines() {
  return db.all<{ id: string; date: number; account: string }>(
    `SELECT id, date, account FROM v_transactions_internal
      WHERE parent_id = 'parent' AND tombstone = 0 ORDER BY id`,
  );
}

describe('split lines stay with their parent', () => {
  it('moves the lines when only the parent date is changed', async () => {
    await setup();

    // What a rule setting the date, or bank sync updating dates, sends
    await batchUpdateTransactions({
      updated: [{ id: 'parent', date: '2024-02-01' }],
    });

    expect(await getLines()).toEqual([
      { id: 'line1', date: 20240201, account: 'one' },
      { id: 'line2', date: 20240201, account: 'one' },
    ]);
  });

  it('puts a line back when only the line date is changed', async () => {
    await setup();

    await batchUpdateTransactions({
      updated: [{ id: 'line1', date: '2024-02-01' }],
    });

    expect(await getLines()).toEqual([
      { id: 'line1', date: 20240131, account: 'one' },
      { id: 'line2', date: 20240131, account: 'one' },
    ]);
  });

  it('moves the lines, and the transfer on a line, with the parent account', async () => {
    await setup();

    await batchUpdateTransactions({
      updated: [{ id: 'parent', account: 'two' }],
    });

    expect(await getLines()).toEqual([
      { id: 'line1', date: 20240131, account: 'two' },
      { id: 'line2', date: 20240131, account: 'two' },
    ]);
    // The other side of the transfer line now comes from account two
    const line2 = await db.getTransaction('line2');
    const counterpart = await db.getTransaction(line2.transfer_id);
    expect(counterpart.account).toBe('three');
    expect(counterpart.payee).toBe('transfer-two');
  });

  it('gives lines moved by a merge the kept transaction date', async () => {
    await setup();
    // An imported duplicate a day later: merge keeps it and takes the lines
    await db.insertTransaction({
      id: 'imported',
      account: 'one',
      amount: -100,
      date: '2024-02-01',
      imported_id: 'bank-1',
    });

    expect(
      await mergeTransactions([{ id: 'parent' }, { id: 'imported' }]),
    ).toBe('imported');

    const lines = await db.all<{ id: string; date: number }>(
      `SELECT id, date FROM v_transactions_internal
        WHERE parent_id = 'imported' AND tombstone = 0 ORDER BY id`,
    );
    expect(lines).toEqual([
      { id: 'line1', date: 20240201 },
      { id: 'line2', date: 20240201 },
    ]);
  });

  it('repairs lines that were left on another date', async () => {
    await setup();
    // Bypass the batch update, as data from an older version or another
    // device can arrive
    await db.updateTransaction({ id: 'line1', date: '2023-12-15' });

    expect(await alignSplitLines()).toEqual(['line1']);
    expect(await getLines()).toEqual([
      { id: 'line1', date: 20240131, account: 'one' },
      { id: 'line2', date: 20240131, account: 'one' },
    ]);
    expect(await alignSplitLines()).toEqual([]);
  });
});

