import { beforeEach, describe, expect, it } from 'vitest';

import * as db from '#server/db';

import {
  openingBalanceIdParts,
  resolveOpeningBalances,
} from './opening-balances';
import { stableId } from './stable-ids';

beforeEach(global.emptyDatabase());

// What bank sync adds when it links the account
function bankSyncOpeningBalance(date: string, amount: number) {
  return db.insertTransaction({
    id: stableId(...openingBalanceIdParts('one', date, amount)),
    account: 'one',
    amount,
    date,
    starting_balance_flag: true,
  });
}

async function setup() {
  await db.insertAccount({ id: 'one', name: 'Joint' });
  // Laptop A linked on day 1: its window starts on 2 November
  await bankSyncOpeningBalance('2026-11-02', 100000);
  await db.insertTransaction({
    id: 'tesco',
    account: 'one',
    amount: -1250,
    date: '2026-11-02',
  });
  await db.insertTransaction({
    id: 'salary',
    account: 'one',
    amount: 250000,
    date: '2026-11-05',
  });
}

function openingBalances() {
  return db.all<{ date: number; amount: number }>(
    `SELECT date, amount FROM v_transactions_internal_alive
      WHERE starting_balance_flag = 1 ORDER BY date`,
  );
}

async function balance() {
  const { total } = await db.first<{ total: number }>(
    `SELECT SUM(amount) AS total FROM v_transactions_internal_alive
      WHERE account = 'one' AND is_parent = 0`,
  );
  return total;
}

describe('resolveOpeningBalances', () => {
  it('leaves an account with one opening balance alone', async () => {
    await setup();

    expect(await resolveOpeningBalances()).toEqual([]);
    expect(await openingBalances()).toEqual([
      { date: 20261102, amount: 100000 },
    ]);
  });

  it('keeps the earliest whole opening balance and removes a later one that adds up', async () => {
    await setup();
    // Laptop B linked a day later: its window starts on 3 November, so its
    // opening balance already includes the Tesco transaction
    await bankSyncOpeningBalance('2026-11-03', 98750);
    expect(await balance()).toBe(100000 - 1250 + 250000 + 98750);

    expect(await resolveOpeningBalances()).toEqual([]);
    expect(await openingBalances()).toEqual([
      { date: 20261102, amount: 100000 },
    ]);
    expect(await balance()).toBe(100000 - 1250 + 250000);
  });

  it('reports a later opening balance that does not add up', async () => {
    await setup();
    await bankSyncOpeningBalance('2026-11-03', 103750);

    expect(await resolveOpeningBalances()).toEqual([
      {
        accountName: 'Joint',
        date: '2026-11-02',
        amount: 100000,
        otherDate: '2026-11-03',
        otherAmount: 103750,
        expectedAmount: 98750,
        removed: true,
      },
    ]);
    expect(await openingBalances()).toEqual([
      { date: 20261102, amount: 100000 },
    ]);
  });

  it('reports, but does not remove, an opening balance changed by hand', async () => {
    await setup();
    const id = await bankSyncOpeningBalance('2026-11-03', 98750);
    await db.updateTransaction({ id, amount: 99000 });

    expect(await resolveOpeningBalances()).toEqual([
      expect.objectContaining({ otherAmount: 99000, removed: false }),
    ]);
    expect(await openingBalances()).toHaveLength(2);
  });
});
